const items = $input.first().json.result.points
const categorias = items.reduce((acc, item) => {
  const rawCategory = item.payload?.metadata?.categoria?.trim();

  if (rawCategory) {
    const pascalCased = rawCategory
      .toLowerCase()
      .split(' ')
      .filter(word => word.length > 0)
      .map(word => 
        word.charAt(0).toUpperCase() + word.slice(1)
      )
      .join('');

    if (!acc.includes(pascalCased)) {
      acc.push(pascalCased);
    }
  }

  return acc;
}, []);

return { items: categorias, tipo: "Categoria" };

const items = $('Obtiene productos por  categoria').first().json.result.points;

const group = items.reduce((acc, item) => {
  const titulo = item.payload?.metadata?.titulo?.trim();
  const categoria = item.payload?.metadata?.categoria?.trim() || "Sin Categoría";
  const main_image_url = item.payload?.main_image_url ?? null;

  if (titulo) {
    if (!acc[categoria]) {
      acc[categoria] = {
        categoria: categoria,
        productos: []
      };
    }

    const isDuplicate = acc[categoria].productos.some(p => p.titulo === titulo);

    if (!isDuplicate) {
      acc[categoria].productos.push({ titulo, main_image_url });
    }
  }

  return acc;
}, {});

return Object.values(group);

const items = $input.first().json.result.points

const group = items.reduce((acc, item) => {
  const { titulo, categoria, precio, stock, descripcion, Color, sku } = item.payload?.metadata;
  const { main_image_url, variant_image_url } = item.payload ?? {};
  const colores = {
    color : Color,
    sku: sku,
    main_image_url: main_image_url ?? null,
    variant_image_url: variant_image_url ?? null
  }

  if (titulo) {
    if (!acc[categoria]) {
      acc[categoria] = {
        categoria: categoria,
        productos: []
      };
    }

   const existingProduct = acc[categoria].productos.find(p => p.titulo === titulo);

    if (!existingProduct) {
      acc[categoria].productos.push({ 
        titulo : titulo,
        colores: [colores],
        main_image_url: main_image_url ?? null,
        precio: precio,
        descripcion: descripcion,
        stock: stock
      });
    } else {
      existingProduct.colores.push(colores);
    }
  }

  return acc;
}, {});

return Object.values(group);

const items = $input.all();
const products = items[0]?.json?.productos.split(",");

const result = products.map((product) => {
  return {
    filter: {
      must: [
        {
          key: "metadata.titulo",
          match: {
            text: product.toUpperCase(),
          },
        },
      ],
    },
    limit: 30,
    with_payload: true,
  };
});

return result;

